import{_ as e,o as d,c as o,a2 as c}from"./chunks/framework.BEUshCVJ.js";const p=JSON.parse('{"title":"Settings","description":"","frontmatter":{},"headers":[],"relativePath":"reference/settings.md","filePath":"reference/settings.md","lastUpdated":1793313192000}'),r={name:"reference/settings.md"};function a(i,t,s,n,h,l){return d(),o("div",null,[...t[0]||(t[0]=[c('<h1 id="settings" tabindex="-1">Settings <a class="header-anchor" href="#settings" aria-label="Permalink to &quot;Settings&quot;">​</a></h1><p>This page lists every setting, where to find it in the app, and its key in <code>settings.json</code>. You normally change settings in the app; editing the file by hand is only needed for automation or recovery.</p><h2 id="where-settings-are-stored" tabindex="-1">Where settings are stored <a class="header-anchor" href="#where-settings-are-stored" aria-label="Permalink to &quot;Where settings are stored&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Install</th><th>Settings folder</th></tr></thead><tbody><tr><td>Scoop</td><td><code>scoop\\persist\\meetcue\\config</code> (kept across updates)</td></tr><tr><td>Portable zip</td><td><code>config</code> next to <code>MeetCue.exe</code></td></tr><tr><td>Fallback when that folder isn&#39;t writable</td><td><code>%APPDATA%\\MeetCue</code></td></tr></tbody></table><p>The folder holds <code>settings.json</code>, <code>latency-history.json</code>, <code>usage.jsonl</code>, <code>logs\\</code> and <code>practice\\</code>. <strong>Settings › Diagnostics › About</strong> shows the folder in use. API keys are never stored here; they live in Windows Credential Manager.</p><p>If <code>settings.json</code> can&#39;t be read, MeetCue renames it to <code>settings.json.bad</code> and starts with defaults.</p><h2 id="general" tabindex="-1">General <a class="header-anchor" href="#general" aria-label="Permalink to &quot;General&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Setting</th><th>Key</th><th>Default</th></tr></thead><tbody><tr><td>Interface language</td><td><code>general.uiLanguage</code>: <code>system</code>, <code>en</code>, <code>zh-CN</code></td><td><code>system</code></td></tr><tr><td>Hint language</td><td><code>general.hintLanguage</code>: <code>followQuestion</code>, <code>en</code>, <code>zh-CN</code></td><td><code>followQuestion</code></td></tr><tr><td>Accent color</td><td><code>general.accent</code></td><td><code>#F5B841</code></td></tr><tr><td>Font (empty: the system font)</td><td><code>general.fontFamily</code></td><td>empty</td></tr><tr><td>Start MeetCue when I sign in</td><td><code>general.autostart</code></td><td><code>false</code></td></tr><tr><td>Hide the panel when sharing the screen</td><td><code>overlay.hideInScreenShare</code></td><td><code>true</code></td></tr><tr><td>Let clicks pass through the panel</td><td><code>overlay.clickThrough</code></td><td><code>false</code></td></tr><tr><td>Panel layout</td><td><code>overlay.mode</code>: <code>full</code>, <code>mini</code>, <code>hidden</code></td><td><code>full</code></td></tr><tr><td>Panel position (drag the panel; <strong>Reset panel position</strong> puts it back)</td><td><code>overlay.x</code>, <code>overlay.y</code></td><td>top right</td></tr><tr><td>Panel size in logical pixels (empty: 440 wide, nearly the screen&#39;s height)</td><td><code>overlay.width</code>, <code>overlay.height</code></td><td>empty</td></tr><tr><td>Panel text size, 0.8 to 1.6</td><td><code>overlay.textScale</code></td><td><code>1</code></td></tr><tr><td>Panel opacity, 0.3 to 1</td><td><code>overlay.opacity</code></td><td><code>1</code></td></tr><tr><td>Saved spots: position, size and layout for each spot shortcut</td><td><code>overlay.spots</code></td><td>three empty spots</td></tr><tr><td>Run setup again</td><td><code>general.wizardCompleted</code></td><td><code>false</code> until setup is finished</td></tr></tbody></table><p><strong>Erase all data</strong>, at the bottom of the General tab, deletes API keys, settings and every local record after you type the confirmation word, then restarts MeetCue. See <a href="/meetcue/reference/privacy#delete-your-data">Delete your data</a>.</p><p>Every setting applies as soon as it&#39;s changed, including during a meeting: models, keys, languages and hint settings take effect for the next question, and recognition and audio capture switch without restarting the session.</p><h2 id="audio" tabindex="-1">Audio <a class="header-anchor" href="#audio" aria-label="Permalink to &quot;Audio&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Setting</th><th>Key</th><th>Default</th></tr></thead><tbody><tr><td>Microphone (you)</td><td><code>audio.micDevice</code>; empty uses the system default</td><td>empty</td></tr><tr><td>Other participants</td><td><code>audio.remoteSource</code>: <code>allSystemSound</code></td><td><code>allSystemSound</code></td></tr><tr><td>Meeting languages</td><td><code>audio.languages</code>, e.g. <code>[&quot;zh&quot;, &quot;en&quot;]</code></td><td><code>[&quot;zh&quot;, &quot;en&quot;]</code></td></tr><tr><td>Microphone voice threshold</td><td><code>audio.vadThresholdDb</code>, in dBFS, −70 to −10</td><td><code>-45</code></td></tr><tr><td>System sound voice threshold</td><td><code>audio.remoteVadThresholdDb</code>, in dBFS, −70 to −10</td><td><code>-60</code></td></tr><tr><td>Boost quiet voices from the meeting</td><td><code>audio.boostQuietVoices</code></td><td><code>true</code></td></tr><tr><td>Sentence end after silence</td><td><code>audio.endpointSilenceMs</code>, 500 to 3000 ms</td><td><code>700</code></td></tr></tbody></table><h2 id="providers-and-cost" tabindex="-1">Providers and cost <a class="header-anchor" href="#providers-and-cost" aria-label="Permalink to &quot;Providers and cost&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Setting</th><th>Key</th></tr></thead><tbody><tr><td>Speech recognition</td><td><code>providers.asr</code></td></tr><tr><td>Question detection model</td><td><code>providers.detect</code></td></tr><tr><td>Hint model</td><td><code>providers.hints</code></td></tr><tr><td>Base URL per provider (required for OpenAI-compatible, optional for Anthropic)</td><td><code>providers.baseUrls</code>, for example <code>{&quot;openai-compatible&quot;: &quot;https://host/v1&quot;}</code>. Older files with <code>providers.openaiBaseUrl</code> are moved here when loaded</td></tr><tr><td>HTTPS proxy</td><td><code>providers.proxy</code>; empty uses the system proxy</td></tr><tr><td>Prices you entered (listed under <strong>Your own prices</strong>, where they can be removed)</td><td><code>providers.pricingOverrides</code></td></tr><tr><td>Cost estimate assumptions (<strong>How estimates are calculated</strong>)</td><td><code>providers.estimate</code>: <code>speechRatio</code>, <code>questionsPerHour</code>, <code>hintInputTokens</code>, <code>hintOutputTokens</code>, <code>detectInputTokens</code>, <code>detectOutputTokens</code>, <code>systemTokens</code>, <code>cancelOverhead</code></td></tr><tr><td>Budget</td><td><code>providers.budget.sessionLimitUsd</code>, <code>monthlyLimitUsd</code>, <code>onLimit</code> (<code>notifyOnly</code>, <code>pauseHints</code>, <code>endSession</code>)</td></tr></tbody></table><p>Each of <code>asr</code>, <code>detect</code> and <code>hints</code> has <code>provider</code>, <code>model</code> and <code>endpoint</code>. The endpoint is <code>{&quot;mode&quot;: &quot;auto&quot;}</code> (fastest measured) or <code>{&quot;mode&quot;: &quot;host&quot;, &quot;host&quot;: &quot;&lt;host name&gt;&quot;}</code>.</p><h2 id="hints" tabindex="-1">Hints <a class="header-anchor" href="#hints" aria-label="Permalink to &quot;Hints&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Setting</th><th>Key</th><th>Default</th></tr></thead><tbody><tr><td>My role</td><td><code>hints.role</code></td><td>empty</td></tr><tr><td>Briefing material</td><td><code>hints.materials</code> (name, path and extracted text)</td><td>none</td></tr><tr><td>Only questions directed at me</td><td><code>hints.onlyDirectedToMe</code></td><td><code>false</code></td></tr><tr><td>Queue interruptions</td><td><code>hints.queueInterruptions</code></td><td><code>true</code></td></tr><tr><td>Track what I&#39;ve said</td><td><code>hints.trackCoverage</code></td><td><code>true</code></td></tr><tr><td>Early trigger</td><td><code>hints.earlyTrigger</code></td><td><code>true</code></td></tr><tr><td>Write hints while checking the question</td><td><code>hints.speculativeHints</code></td><td><code>true</code></td></tr></tbody></table><h2 id="shortcuts" tabindex="-1">Shortcuts <a class="header-anchor" href="#shortcuts" aria-label="Permalink to &quot;Shortcuts&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Setting</th><th>Key</th><th>Default</th></tr></thead><tbody><tr><td>Start or pause listening</td><td><code>hotkeys.toggleCapture</code></td><td><code>Ctrl+Alt+Space</code></td></tr><tr><td>Cycle the panel</td><td><code>hotkeys.cyclePanel</code></td><td><code>Ctrl+Alt+H</code></td></tr><tr><td>Previous question</td><td><code>hotkeys.focusPrev</code></td><td><code>Ctrl+Alt+[</code></td></tr><tr><td>Next question</td><td><code>hotkeys.focusNext</code></td><td><code>Ctrl+Alt+]</code></td></tr><tr><td>Mark answered</td><td><code>hotkeys.markAnswered</code></td><td><code>Ctrl+Alt+Enter</code></td></tr><tr><td>Move the panel up</td><td><code>hotkeys.moveUp</code></td><td><code>Ctrl+Alt+Shift+Up</code></td></tr><tr><td>Move the panel down</td><td><code>hotkeys.moveDown</code></td><td><code>Ctrl+Alt+Shift+Down</code></td></tr><tr><td>Move the panel left</td><td><code>hotkeys.moveLeft</code></td><td><code>Ctrl+Alt+Shift+Left</code></td></tr><tr><td>Move the panel right</td><td><code>hotkeys.moveRight</code></td><td><code>Ctrl+Alt+Shift+Right</code></td></tr><tr><td>Go to saved spot 1, 2, 3</td><td><code>hotkeys.spot1</code>, <code>spot2</code>, <code>spot3</code></td><td><code>Ctrl+Alt+Shift+1</code>, <code>2</code>, <code>3</code></td></tr><tr><td>Hide the panel for a few seconds</td><td><code>hotkeys.peek</code></td><td><code>Ctrl+Alt+Shift+P</code></td></tr><tr><td>Let clicks pass through the panel (on/off)</td><td><code>hotkeys.clickThrough</code></td><td><code>Ctrl+Alt+Shift+T</code></td></tr></tbody></table><h2 id="practice" tabindex="-1">Practice <a class="header-anchor" href="#practice" aria-label="Permalink to &quot;Practice&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Setting</th><th>Key</th><th>Default</th></tr></thead><tbody><tr><td>Speech-to-text for the questions</td><td><code>practice.playback</code>: <code>realPipeline</code> (on), <code>simulatedLatency</code> (off)</td><td><code>realPipeline</code></td></tr><tr><td>Hint level</td><td><code>practice.hintLevel</code>: <code>full</code>, <code>headsOnly</code>, <code>delayed</code>, <code>off</code></td><td><code>full</code></td></tr><tr><td>Delay for delayed hints (s)</td><td><code>practice.hintDelayS</code></td><td><code>5</code></td></tr><tr><td>Pause that ends an answer (s)</td><td><code>practice.answerPauseS</code></td><td><code>3</code></td></tr><tr><td>Reminder when you haven&#39;t started (s)</td><td><code>practice.nudgeAfterS</code></td><td><code>20</code></td></tr><tr><td>Follow-up probability</td><td><code>practice.followUpProbability</code></td><td><code>0.3</code></td></tr><tr><td>Speech rate</td><td><code>practice.speechRate</code></td><td><code>1.0</code></td></tr><tr><td>Speech-to-text for my answers</td><td><code>practice.recognizeMe</code></td><td><code>true</code></td></tr><tr><td>English voice</td><td><code>practice.voiceEn</code>: a Windows voice id, empty for the first one</td><td><code>&quot;&quot;</code></td></tr><tr><td>Chinese voice</td><td><code>practice.voiceZh</code>: a Windows voice id, empty for the first one</td><td><code>&quot;&quot;</code></td></tr><tr><td>Stop reading when I start speaking</td><td><code>audio.stopTtsOnSpeech</code></td><td><code>true</code></td></tr><tr><td>Filler words</td><td><code>practice.fillersZh</code>, <code>practice.fillersEn</code></td><td>see <a href="/meetcue/guide/practice#review-report">Practice mode</a></td></tr></tbody></table><h2 id="diagnostics" tabindex="-1">Diagnostics <a class="header-anchor" href="#diagnostics" aria-label="Permalink to &quot;Diagnostics&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Setting</th><th>Key</th><th>Default</th></tr></thead><tbody><tr><td>Debug logging</td><td><code>diagnostics.debugLogging</code></td><td><code>false</code></td></tr></tbody></table>',23)])])}const g=e(r,[["render",a]]);export{p as __pageData,g as default};
